    const acts=(appState.activities||[]).slice(0,6);q('#xp-home-timeline').innerHTML=acts.length?acts.map(a=>`<div class="xp-attention-item"><span class="xp-attention-icon">${svg('spark')}</span><div><b>${safe(a.text||'Actividad')}</b><small>${safe(when(a.at))}</small></div></div>`).join(''):'<div class="xp-empty">La actividad aparecerá aquí.</div>';
    const rec=[];if(waiting.length)rec.push({tone:'ai',title:'Priorizá clientes en espera',copy:`Hay ${waiting.length} conversación${waiting.length===1?'':'es'} esperando respuesta.`,view:'crm'});if(low.length)rec.push({tone:'warning',title:'Revisá reposición de stock',copy:`${low.length} producto${low.length===1?'':'s'} llegó al mínimo.`,view:'stock'});const unassigned=open.filter(d=>!d.ownerUserId);if(unassigned.length)rec.push({tone:'ai',title:'Distribuí negociaciones sin dueño',copy:`${unassigned.length} cliente${unassigned.length===1?'':'s'} sin responsable.`,view:'crm'});if(appState.connection?.status==='connected'&&!critical)rec.push({tone:'',title:'Canal estable',copy:'WhatsApp figura conectado y operativo.',view:'whatsapp'});q('#xp-home-recommendations').innerHTML=rec.length?rec.map((x,i)=>`<article class="xp-attention-item ${x.tone}"><span class="xp-attention-icon">${svg(x.tone==='ai'?'ai':x.tone==='warning'?'alert':'whatsapp')}</span><div><b>${safe(x.title)}</b><small>${safe(x.copy)}</small></div><button data-xp-rec="${i}" type="button">Ver</button></article>`).join(''):'<div class="xp-empty">Sin recomendaciones nuevas.</div>';q('#xp-home-recommendations').onclick=e=>{const b=e.target.closest('[data-xp-rec]');if(b)switchView(rec[Number(b.dataset.xpRec)].view)};
